package com.oms.supplychain.service.wms;
import org.springframework.stereotype.Component;
import org.w3c.dom.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.stream.Collectors;
import static com.oms.supplychain.service.wms.WmsStore.*;
import static com.oms.supplychain.service.wms.QimenProtocol.*;

/** Dedicated Qimen return order protocol. Purchase entry orders remain unchanged. */
@Component public class QimenReturnProtocol {
    private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
    private static String value(Element e,String key){Element n=child(e,key);return n==null?"":n.getTextContent().trim();}
    public WmsProtocol.Wire request(Map<String,Object> c,String secret,String action,Map<String,Object> task){require(Arrays.asList("CREATE","QUERY","CANCEL").contains(action),"退回仓库操作无效");require("QIMEN".equals(c.get("provider"))&&"2.0".equals(c.get("api_version")),"换货退回目前需要奇门2.0连接");String orderType="REFUND_IN".equals(task.get("business_type"))?"THRK":"HHRK";String shared=tag("returnOrderCode",task.get("return_sn"))+tag("ownerCode",task.get("external_owner"))+tag("warehouseCode",task.get("external_warehouse")),body;
        String sender="";if(task.get("sender_json")!=null)try{Map<String,Object> info=new com.fasterxml.jackson.databind.ObjectMapper().readValue(task.get("sender_json").toString(),Map.class);StringBuilder b=new StringBuilder("<senderInfo>");for(String field:Arrays.asList("name","mobile","province","city","area","town","detailAddress","oaid"))b.append(tag(field,info.get(field)));sender=b.append("</senderInfo>").toString();}catch(Exception e){throw new IllegalArgumentException("退回寄件人快照无法解析");}
        if("CREATE".equals(action)){StringBuilder detail=new StringBuilder();if(task.get("order_lines") instanceof List){for(Object raw:(List<?>)task.get("order_lines")){Map<?,?> line=(Map<?,?>)raw;detail.append("<orderLine>").append(tag("orderLineNo",line.get("line_no"))).append(tag("sourceOrderCode",line.get("platform_tid"))).append(tag("ownerCode",task.get("external_owner"))).append(tag("itemCode",line.get("sku_sn"))).append(tag("planQty",line.get("quantity"))).append("</orderLine>");}}body="<request><returnOrder>"+shared+tag("orderType",orderType)+tag("sourcePlatformCode","TM")+tag("preDeliveryOrderCode",task.get("original_shipment_sn"))+tag("logisticsCode",task.getOrDefault("return_carrier","OTHER"))+tag("expressCode",task.get("return_waybill"))+tag("orderCreateTime",LocalDateTime.parse(text(task.get("create_time")).replace(' ','T')).format(TIME))+tag("remark","OMS退回 "+task.getOrDefault("business_sn",task.get("exchange_sn"))+" 退回包裹 "+task.getOrDefault("parcel_sn",""))+sender+"</returnOrder><orderLines>"+(detail.length()>0?detail.toString():"<orderLine>"+tag("orderLineNo",1)+tag("sourceOrderCode",task.get("platform_tid"))+tag("ownerCode",task.get("external_owner"))+tag("itemCode",task.get("sku_sn"))+tag("planQty",task.get("quantity"))+tag("inventoryType","ZP")+"</orderLine>")+"</orderLines></request>"; }

        else if("CANCEL".equals(action))body="<request>"+tag("orderCode",task.get("return_sn"))+tag("orderId",task.get("external_order"))+tag("orderType",orderType)+tag("ownerCode",task.get("external_owner"))+tag("warehouseCode",task.get("external_warehouse"))+tag("cancelReason",task.get("cancel_reason"))+"</request>";
        else body="<request>"+shared+tag("returnOrderId",task.get("external_order"))+tag("page",1)+tag("pageSize",100)+"</request>";
        Map<String,String> params=new TreeMap<>();params.put("app_key",text(c.get("app_key")));params.put("customerId",text(c.get("customer_id")));params.put("method","CANCEL".equals(action)?"taobao.qimen.order.cancel":"taobao.qimen.returnorder."+("CREATE".equals(action)?"create":"query"));params.put("format","xml");params.put("sign_method","md5");params.put("v","2.0");params.put("timestamp",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(TIME));params.put("sign",sign(params,body,secret));String query=params.entrySet().stream().map(e->enc(e.getKey())+"="+enc(e.getValue())).collect(Collectors.joining("&"));return new WmsProtocol.Wire(text(c.get("endpoint"))+"?"+query,body,"application/xml;charset=UTF-8");
    }
    public static String documentSn(String body){Element head=child(parse(body),"returnOrder");return head==null?"":value(head,"returnOrderCode");}
    public static boolean refundDocument(String body){Element head=child(parse(body),"returnOrder");return head!=null&&(value(head,"returnOrderCode").startsWith("THK")||value(head,"returnOrderCode").startsWith("RPK"));}
    public static boolean parcelDocument(String body){Element head=child(parse(body),"returnOrder");return head!=null&&value(head,"returnOrderCode").startsWith("RPK");}
    public WmsProtocol.Reply reply(String action,String body){Element root=parse(body);require("response".equals(root.getTagName()),"仓库响应结构无效");String flag=value(root,"flag");require(Arrays.asList("success","failure").contains(flag),"仓库未返回明确结果");WmsProtocol.Reply reply=new WmsProtocol.Reply();reply.success="success".equals(flag);reply.code=value(root,"code");reply.message=value(root,"message");Element head=child(root,"returnOrder");if(head==null)head=root;reply.externalOrder=value(head,"returnOrderId");reply.documentSn=value(head,"returnOrderCode");reply.owner=value(head,"ownerCode");reply.warehouse=value(head,"warehouseCode");reply.status=value(head,"status");return reply;}
    public WmsProtocol.Receipt callback(Map<String,Object> c,String secret,Map<String,String> params,String body){require("taobao.qimen.returnorder.confirm".equals(params.get("method")),"退回通知方法无效");require("md5".equals(params.get("sign_method"))&&"2.0".equals(params.get("v")),"退回通知签名版本无效");require(text(c.get("app_key")).equals(params.get("app_key"))&&text(c.get("customer_id")).equals(params.get("customerId")),"退回通知连接身份不一致");LocalDateTime sent;try{sent=LocalDateTime.parse(params.get("timestamp"),TIME);}catch(Exception e){throw new IllegalArgumentException("退回通知时间无效");}require(Math.abs(Duration.between(sent,LocalDateTime.now(ZoneId.of("Asia/Shanghai"))).getSeconds())<=600,"退回通知时间超出范围");require(MessageDigest.isEqual(sign(params,body,secret).getBytes(StandardCharsets.UTF_8),text(params.get("sign")).getBytes(StandardCharsets.UTF_8)),"退回通知验签失败");Element root=parse(body),head=child(root,"returnOrder");require(head!=null,"缺少退回单据头");require(Arrays.asList("HHRK","THRK").contains(value(head,"orderType")),"退回单据类型无效");WmsProtocol.Receipt r=new WmsProtocol.Receipt();r.ticketSn=value(head,"returnOrderCode");r.externalOrder=value(head,"returnOrderId");r.warehouse=value(head,"warehouseCode");r.owner=value(head,"ownerCode");r.messageId=value(head,"outBizCode");String confirm=value(head,"confirmType");require(Arrays.asList("0","1").contains(confirm),"请明确退回是否最终确认");r.complete="0".equals(confirm);r.status=r.complete?"FULFILLED":"PARTFULFILLED";Element lines=child(root,"orderLines");require(lines!=null,"退回明细缺失");for(Element line:children(lines,"orderLine")){r.sourceLineCount++;String sku=value(line,"itemCode"),owner=value(line,"ownerCode");int actual=quantity(value(line,"actualQty"));Element batches=child(line,"batchs");if(batches!=null){int sum=0;for(Element batch:children(batches,"batch")){int q=quantity(value(batch,"actualQty"));sum=Math.addExact(sum,q);WmsProtocol.Line parsed=line(sku,owner,value(batch,"batchCode"),value(batch,"inventoryType"),q);parsed.lineNo=value(line,"orderLineNo");r.lines.add(parsed);}require(sum==actual,"退回批次实收数量不一致");}else {WmsProtocol.Line parsed=line(sku,owner,value(line,"batchCode"),value(line,"inventoryType"),actual);parsed.lineNo=value(line,"orderLineNo");r.lines.add(parsed);}}require(r.sourceLineCount>0&&r.sourceLineCount<=100&&r.lines.size()<=500,"退回行数不完整或超过限制");return r;}
    private static int quantity(String value){long q=id(value);require(q>=0&&q<=100000000,"退回数量无效");return (int)q;}
    private WmsProtocol.Line line(String sku,String owner,String batch,String type,int qty){require(Arrays.asList("","ZP","CC","JS","XS","FP").contains(type),"退回库存类型无效");WmsProtocol.Line l=new WmsProtocol.Line();l.sku=sku;l.owner=owner;l.batch=batch;if(type.isEmpty()||"ZP".equals(type))l.good=qty;else l.bad=qty;return l;}
}
